/** Exact symbolic mechanics and original scripted Episode graphs for material
 * Hunters. Episode numbers are encounter data, not recovered ordinary balance.
 * No active profile/ownership mutation; selection is explicit and read-only.
 */
/** Read-only readiness; exact text/cost/art identity is separate from native
 * ordinary admission and final ordinary effect magnitudes. */
export function materialSkillReadiness(refId: string) {
  const row = MATERIAL_SKILL_EVIDENCE.find(row => row.refId === refId);
  if (!row) throw new Error("Unknown material Hunter reference");
  return {
    refId: row.refId, name: row.name, rageCost: row.rageCost,
    symbolicSlots: [...new Set(row.symbolic.map(record => record.slot))],
    scriptedGraphRows: row.episodeCandidates.filter(candidate => candidate.compatibleBaseIdentity && candidate.skill.length > 0)
      .map(candidate => ({ sourceIndex: candidate.sourceIndex, actorId: candidate.actorId,
        slotTypes: candidate.skill.map(skill => skill.type),
        episodeRageCost: candidate.skill.find(skill => skill.type === 1)?.cost ?? null,
        ordinaryCostAgreement: candidate.skill.find(skill => skill.type === 1)?.cost === row.rageCost })),
    originalOrdinaryMagnitudes: "UNKNOWN", ordinaryGrowth: "UNKNOWN",
    nativeOrdinaryActivation: "PENDING", activeIntegration: false,
    artwork: structuredClone([...row.art]),
    labels: structuredClone([...row.labels]),
  };
}

/** The index pins duplicate Episode IDs to distinct source records. This API
 * returns only the unchanged original encounter graph. It does not fill absent
 * slots, invent growth, choose an ordinary donor or publish a live reference. */
export function selectMaterialEpisodeGraph(refId: string, sourceIndex: number) {
  if (!Number.isSafeInteger(sourceIndex) || sourceIndex < 0) throw new Error("Explicit original Episode row index required");
  const row = MATERIAL_SKILL_EVIDENCE.find(row => row.refId === refId);
  if (!row) throw new Error("Unknown material Hunter reference");
  const source = row.episodeCandidates.find(candidate => candidate.sourceIndex === sourceIndex);
  if (!source || !source.compatibleBaseIdentity || source.skill.length === 0)
    throw new Error("No compatible nonempty original Episode graph at selected row");
  return {
    evidenceClass: "RECOVERED_EPISODE", ordinaryAdoptionPolicyRequired: true,
    provenance: { ...MATERIAL_SKILL_SOURCE_PINS.episode, locator: `/${sourceIndex}/skill` },
    source: structuredClone(source),
    ordinaryRageCost: row.rageCost,
    episodeRageCost: source.skill.find(skill => skill.type === 1)?.cost ?? null,
    ordinaryCostAgreement: source.skill.find(skill => skill.type === 1)?.cost === row.rageCost,
    originalOrdinaryMagnitudes: "UNKNOWN", ordinaryGrowth: "UNKNOWN",
    nativeOrdinaryActivation: "PENDING", activeIntegration: false,
  };
}
